-- ANGELCARE 360 CUSTOMER MEGA ZIP 1 — PRODUCT CONSTITUTION & EXPERIENCE KERNEL
begin;
create extension if not exists pgcrypto;

create table if not exists public.angelcare360_operator_product_domains (
 id uuid primary key default gen_random_uuid(), domain_key text not null unique, name text not null, description text,
 status text not null default 'published', sort_order integer not null default 0, version text not null default '1.0.0',
 created_at timestamptz not null default now(), updated_at timestamptz not null default now()
);
create table if not exists public.angelcare360_operator_product_capabilities (
 id uuid primary key default gen_random_uuid(), capability_key text not null unique,
 module_id uuid not null references public.angelcare360_operator_product_modules(id) on delete cascade,
 name text not null, description text, status text not null default 'draft', sellability text not null default 'package_included',
 runtime_maturity text not null default 'operational', version text not null default '1.0.0', sort_order integer not null default 0,
 configuration_schema jsonb not null default '{}'::jsonb, created_at timestamptz not null default now(), updated_at timestamptz not null default now()
);
create table if not exists public.angelcare360_operator_product_services (
 id uuid primary key default gen_random_uuid(), service_code text not null unique, name text not null, description text,
 service_type text not null, billing_model text not null, status text not null default 'draft', currency text not null default 'MAD',
 list_price numeric not null default 0, configuration_schema jsonb not null default '{}'::jsonb,
 created_at timestamptz not null default now(), updated_at timestamptz not null default now()
);
create table if not exists public.angelcare360_operator_topup_offers (
 id uuid primary key default gen_random_uuid(), topup_code text not null unique,
 meter_id uuid not null references public.angelcare360_operator_product_meters(id) on delete restrict,
 name text not null, increment numeric not null check(increment>0), status text not null default 'draft',
 price_book_entry_id uuid references public.angelcare360_operator_price_book_entries(id) on delete set null,
 maximum_purchases integer, validity_days integer, approval_required boolean not null default false,
 provisioning_action text not null default 'allocate_capacity', package_policy jsonb not null default '{}'::jsonb,
 created_at timestamptz not null default now(), updated_at timestamptz not null default now()
);
create table if not exists public.angelcare360_operator_product_route_bindings (
 id uuid primary key default gen_random_uuid(), route_path text not null unique, source_path text not null,
 domain_key text not null, module_key text not null, entitlement_module_key text,
 capability_key text not null, feature_key text not null, permission_key text not null,
 visibility_rule_key text not null, provisioning_blueprint_key text not null, label text not null,
 detail_route boolean not null default false, status text not null default 'published',
 created_at timestamptz not null default now(), updated_at timestamptz not null default now()
);
create table if not exists public.angelcare360_operator_product_operations (
 id uuid primary key default gen_random_uuid(), operation_key text not null unique,
 route_path text not null, feature_key text not null, operation_name text not null,
 permission_key text not null, audit_event text not null, mutation_endpoints jsonb not null default '[]'::jsonb,
 source_confidence text not null default 'exact_source_static_audit', status text not null default 'published',
 created_at timestamptz not null default now(), updated_at timestamptz not null default now()
);
create table if not exists public.angelcare360_operator_product_billing_profiles (
 id uuid primary key default gen_random_uuid(), item_type text not null, item_key text not null,
 billing_model text not null, unit text, currency text not null default 'MAD', tax_treatment text not null default 'standard',
 billing_cycle text, minimum_quantity numeric, maximum_quantity numeric, included_allowance numeric,
 proration_policy text, overage_policy text, renewal_policy text, suspension_policy text, cancellation_policy text, refund_policy text,
 status text not null default 'draft', created_at timestamptz not null default now(), updated_at timestamptz not null default now(),
 unique(item_type,item_key)
);
create table if not exists public.angelcare360_operator_product_configuration_ownership (
 id uuid primary key default gen_random_uuid(), configuration_key text not null unique, item_type text not null, item_key text not null,
 owner_role text not null, scope_type text not null, schema jsonb not null default '{}'::jsonb, status text not null default 'published',
 created_at timestamptz not null default now(), updated_at timestamptz not null default now()
);
create table if not exists public.angelcare360_operator_product_provisioning_blueprints (
 id uuid primary key default gen_random_uuid(), blueprint_key text not null unique, item_type text not null, item_key text not null,
 behavior text not null, steps jsonb not null default '[]'::jsonb, idempotency_key_template text,
 rollback_steps jsonb not null default '[]'::jsonb, status text not null default 'published',
 created_at timestamptz not null default now(), updated_at timestamptz not null default now()
);
create table if not exists public.angelcare360_operator_product_visibility_rules (
 id uuid primary key default gen_random_uuid(), rule_key text not null unique, state text not null, behavior text not null,
 label text not null, explanation text, customer_action text, priority integer not null default 100, status text not null default 'published',
 created_at timestamptz not null default now(), updated_at timestamptz not null default now()
);
create table if not exists public.angelcare360_operator_legacy_product_mappings (
 id uuid primary key default gen_random_uuid(), mapping_key text not null unique, legacy_type text not null, legacy_key text not null,
 canonical_type text not null, canonical_key text not null, migration_state text not null default 'mapped', notes text,
 created_at timestamptz not null default now(), updated_at timestamptz not null default now()
);

alter table public.angelcare360_operator_product_modules add column if not exists domain_key text, add column if not exists commercial_class text, add column if not exists billing_classification text default 'included_in_package';
alter table public.angelcare360_operator_product_features add column if not exists capability_id uuid references public.angelcare360_operator_product_capabilities(id) on delete set null, add column if not exists billing_classification text default 'not_separately_billable', add column if not exists operation_keys jsonb not null default '[]'::jsonb;
alter table public.angelcare360_operator_product_meters add column if not exists aggregation_logic jsonb not null default '{}'::jsonb, add column if not exists soft_limit boolean not null default true, add column if not exists freshness_standard text default 'daily';
alter table public.angelcare360_operator_product_addons add column if not exists capability_id uuid references public.angelcare360_operator_product_capabilities(id) on delete set null;
alter table public.angelcare360_operator_package_versions add column if not exists replacement_version_id uuid references public.angelcare360_operator_package_versions(id) on delete set null, add column if not exists upgrade_paths jsonb not null default '[]'::jsonb, add column if not exists downgrade_paths jsonb not null default '[]'::jsonb;

alter table public.angelcare360_operator_product_dependencies drop constraint if exists angelcare360_operator_product_dependencies_source_type_check;
alter table public.angelcare360_operator_product_dependencies drop constraint if exists angelcare360_operator_product_dependencies_target_type_check;
alter table public.angelcare360_operator_product_dependencies drop constraint if exists angelcare360_operator_product_dependencies_relation_type_check;
alter table public.angelcare360_operator_product_dependencies add constraint angelcare360_operator_product_dependencies_source_type_check check(source_type in ('module','capability','feature','addon','meter','service'));
alter table public.angelcare360_operator_product_dependencies add constraint angelcare360_operator_product_dependencies_target_type_check check(target_type in ('module','capability','feature','addon','meter','service'));
alter table public.angelcare360_operator_product_dependencies add constraint angelcare360_operator_product_dependencies_relation_type_check check(relation_type in ('requires','recommends','excludes','conflicts','contains','included_by','replaced_by','migrates_to','requires_configuration','requires_integration','requires_capacity','requires_permission','meters','extends'));
alter table public.angelcare360_operator_package_version_items drop constraint if exists angelcare360_operator_package_version_items_item_type_check;
alter table public.angelcare360_operator_package_version_items add constraint angelcare360_operator_package_version_items_item_type_check check(item_type in ('module','capability','feature','addon','meter','service'));
alter table public.angelcare360_operator_price_book_entries drop constraint if exists angelcare360_operator_price_book_entries_item_type_check;
alter table public.angelcare360_operator_price_book_entries add constraint angelcare360_operator_price_book_entries_item_type_check check(item_type in ('package_version','module','capability','feature','addon','meter','service','topup'));
alter table public.angelcare360_operator_tenant_entitlement_items drop constraint if exists angelcare360_operator_tenant_entitlement_items_item_type_check;
alter table public.angelcare360_operator_tenant_entitlement_items add constraint angelcare360_operator_tenant_entitlement_items_item_type_check check(item_type in ('module','capability','feature','addon','meter','service'));
alter table public.angelcare360_operator_tenant_overrides drop constraint if exists angelcare360_operator_tenant_overrides_item_type_check;
alter table public.angelcare360_operator_tenant_overrides add constraint angelcare360_operator_tenant_overrides_item_type_check check(item_type in ('module','capability','feature','addon','meter','service'));
alter table public.angelcare360_operator_product_domains enable row level security; revoke all on table public.angelcare360_operator_product_domains from anon, authenticated; grant all on table public.angelcare360_operator_product_domains to service_role;
alter table public.angelcare360_operator_product_capabilities enable row level security; revoke all on table public.angelcare360_operator_product_capabilities from anon, authenticated; grant all on table public.angelcare360_operator_product_capabilities to service_role;
alter table public.angelcare360_operator_product_services enable row level security; revoke all on table public.angelcare360_operator_product_services from anon, authenticated; grant all on table public.angelcare360_operator_product_services to service_role;
alter table public.angelcare360_operator_topup_offers enable row level security; revoke all on table public.angelcare360_operator_topup_offers from anon, authenticated; grant all on table public.angelcare360_operator_topup_offers to service_role;
alter table public.angelcare360_operator_product_route_bindings enable row level security; revoke all on table public.angelcare360_operator_product_route_bindings from anon, authenticated; grant all on table public.angelcare360_operator_product_route_bindings to service_role;
alter table public.angelcare360_operator_product_operations enable row level security; revoke all on table public.angelcare360_operator_product_operations from anon, authenticated; grant all on table public.angelcare360_operator_product_operations to service_role;
alter table public.angelcare360_operator_product_billing_profiles enable row level security; revoke all on table public.angelcare360_operator_product_billing_profiles from anon, authenticated; grant all on table public.angelcare360_operator_product_billing_profiles to service_role;
alter table public.angelcare360_operator_product_configuration_ownership enable row level security; revoke all on table public.angelcare360_operator_product_configuration_ownership from anon, authenticated; grant all on table public.angelcare360_operator_product_configuration_ownership to service_role;
alter table public.angelcare360_operator_product_provisioning_blueprints enable row level security; revoke all on table public.angelcare360_operator_product_provisioning_blueprints from anon, authenticated; grant all on table public.angelcare360_operator_product_provisioning_blueprints to service_role;
alter table public.angelcare360_operator_product_visibility_rules enable row level security; revoke all on table public.angelcare360_operator_product_visibility_rules from anon, authenticated; grant all on table public.angelcare360_operator_product_visibility_rules to service_role;
alter table public.angelcare360_operator_legacy_product_mappings enable row level security; revoke all on table public.angelcare360_operator_legacy_product_mappings from anon, authenticated; grant all on table public.angelcare360_operator_legacy_product_mappings to service_role;
create index if not exists ac360_product_capabilities_module_idx on public.angelcare360_operator_product_capabilities(module_id,status);
create index if not exists ac360_product_routes_module_idx on public.angelcare360_operator_product_route_bindings(module_key,capability_key);
create index if not exists ac360_product_operations_route_idx on public.angelcare360_operator_product_operations(route_path,operation_name);
create index if not exists ac360_product_billing_item_idx on public.angelcare360_operator_product_billing_profiles(item_type,item_key);
commit;
